import RESTAdapter from "discourse/adapters/rest";

export default class ChatMessage extends RESTAdapter {
  pathFor(store, type, findArgs) {
    if (findArgs.targetMessageId) {
      return `/chat/lookup/${findArgs.targetMessageId}.json?chat_channel_id=${findArgs.channelId}`;
    }

    let path = `/chat/${findArgs.channelId}/messages.json?page_size=${findArgs.pageSize}`;
    if (findArgs.messageId) {
      path += `&message_id=${findArgs.messageId}`;
    }
    if (findArgs.direction) {
      path += `&direction=${findArgs.direction}`;
    }
    return path;
  }

  apiNameFor() {
    return "chat-message";
  }
}
export default {
  resource: "admin.adminPlugins.show",
  path: "/plugins",
  map() {
    this.route(
      "discourse-chat-incoming-webhooks",
      { path: "hooks" },
      function () {
        this.route("new");
        this.route("edit", { path: "/:id/edit" });
      }
    );
  },
};
/* eslint-disable ember/routes-segments-snake-case */
export default function () {
  this.route("chat", function () {
    this.route("disabled");
    this.route("search");

    this.route("channel", { path: "/c/:channelTitle/:channelId" }, function () {
      this.route("near-message", { path: "/:messageId" });
      this.route("near-message-with-thread", {
        path: "/:messageId/t/:threadId",
      });
      this.route("threads", { path: "/t" });
      this.route("thread", { path: "/t/:threadId" }, function () {
        this.route("near-message", { path: "/:messageId" });
      });
      this.route("pins");
    });

    this.route("direct-messages");
    this.route("channels");
    this.route("starred-channels");
    this.route("threads");

    this.route("new-message");

    this.route(
      "channel.info",
      { path: "/c/:channelTitle/:channelId/info" },
      function () {
        this.route("members");
        this.route("settings");
      }
    );

    this.route("browse", function () {
      this.route("all");
      this.route("closed");
      this.route("open");
      this.route("archived");
    });
    this.route("message", { path: "/message/:messageId" });
  });
}
const EmptyState = <template>
  <div class="c-list-empty-state" ...attributes>
    {{yield}}
  </div>
</template>;

export default EmptyState;
const Item = <template>{{yield @item}}</template>;

export default Item;
import Component from "@glimmer/component";
import { hash } from "@ember/helper";
import { action } from "@ember/object";
import { modifier } from "ember-modifier";
import discourseDebounce from "discourse/lib/debounce";
import { INPUT_DELAY } from "discourse/lib/environment";
import isElementInViewport from "discourse/lib/is-element-in-viewport";
import DConditionalLoadingSpinner from "discourse/ui-kit/d-conditional-loading-spinner";
import EmptyState from "./empty-state.gjs";
import Item from "./item.gjs";

export default class List extends Component {
  loadMore = modifier((element) => {
    this.intersectionObserver = new IntersectionObserver(this.loadCollection);
    this.intersectionObserver.observe(element);

    return () => {
      this.intersectionObserver.disconnect();
    };
  });

  fill = modifier((element) => {
    this.resizeObserver = new ResizeObserver(() => {
      if (isElementInViewport(element)) {
        this.loadCollection();
      }
    });

    this.resizeObserver.observe(element);

    return () => {
      this.resizeObserver.disconnect();
    };
  });

  get itemComponent() {
    return this.args.itemComponent ?? Item;
  }

  get collectionItemsMaybeFiltered() {
    const collection = this.args.collection;
    const filterFn = this.args.filterFn;

    if (filterFn) {
      return filterFn(collection.items);
    } else {
      return collection.items;
    }
  }

  @action
  loadCollection() {
    discourseDebounce(this, this.debouncedLoadCollection, INPUT_DELAY);
  }

  async debouncedLoadCollection() {
    await this.args.collection.load({ limit: 10 }).catch(() => {});
  }

  <template>
    <div class="c-list">
      <div
        class={{if @collection.fetchedOnce "--loaded"}}
        ...attributes
        {{this.fill}}
      >
        {{#each this.collectionItemsMaybeFiltered as |item|}}
          {{yield (hash Item=(component this.itemComponent item=item))}}
        {{else}}
          {{#if @collection.fetchedOnce}}
            {{yield (hash EmptyState=EmptyState)}}
          {{/if}}
        {{/each}}
      </div>

      <div {{this.loadMore}}>
        <br />
      </div>

      <DConditionalLoadingSpinner @condition={{@collection.loading}} />
    </div>
  </template>
}
import Component from "@glimmer/component";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";

export default class MembersCount extends Component {
  get countLabel() {
    return i18n("chat.direct_message_creator.members_counter", {
      count: this.args.count,
      max: this.args.max,
    });
  }

  <template>
    <div
      class={{dConcatClass
        "chat-message-creator__members-count"
        (if (gte @count @max) "-reached-limit")
      }}
    >
      {{this.countLabel}}
    </div>
  </template>
}
import { tracked } from "@glimmer/tracking";
import Category from "discourse/models/category";
import Group from "discourse/models/group";
import User from "discourse/models/user";
import { MATCH_QUALITY_PARTIAL } from "discourse/plugins/chat/discourse/lib/chat-constants";
import ChatChannel from "discourse/plugins/chat/discourse/models/chat-channel";

export default class ChatChatable {
  static create(args = {}) {
    return new ChatChatable(args);
  }

  static createUser(model) {
    return new ChatChatable({
      type: "user",
      model,
      identifier: `u-${model.id}`,
    });
  }

  static createGroup(model) {
    return new ChatChatable({
      type: "group",
      model,
      identifier: `g-${model.id}`,
    });
  }

  static createChannel(model) {
    return new ChatChatable({
      type: "channel",
      model,
      identifier: `c-${model.id}`,
    });
  }

  @tracked identifier;
  @tracked type;
  @tracked model;
  @tracked enabled = true;
  @tracked tracking;
  @tracked matchQuality = MATCH_QUALITY_PARTIAL;

  constructor(args = {}) {
    this.identifier = args.identifier;
    this.type = args.type;
    this.matchQuality = args.match_quality ?? MATCH_QUALITY_PARTIAL;

    switch (this.type) {
      case "channel":
        if (args.model.chatable?.users?.length === 1) {
          this.enabled = args.model.chatable?.users[0].has_chat_enabled;
        }

        if (args.model instanceof ChatChannel) {
          this.model = args.model;
          break;
        }

        this.model = ChatChannel.create(args.model);
        break;
      case "user":
        this.enabled = args.model.has_chat_enabled;

        if (args.model instanceof User) {
          this.model = args.model;
          break;
        }

        this.model = User.create(args.model);
        break;
      case "group":
        this.enabled = args.model.can_chat;

        if (args.model instanceof Group) {
          this.model = args.model;
          break;
        }

        this.model = Group.create(args.model);
        break;
    }
  }

  get isUser() {
    return this.type === "user";
  }

  get isGroup() {
    return this.type === "group";
  }

  get isCategory() {
    return this instanceof Category;
  }
}
import { getOwner, setOwner } from "@ember/owner";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import { bind } from "discourse/lib/decorators";
import { MATCH_QUALITY_PARTIAL } from "discourse/plugins/chat/discourse/lib/chat-constants";
import ChatChatable from "discourse/plugins/chat/discourse/models/chat-chatable";

const MAX_RESULTS = 10;

const TYPE_PRIORITY = {
  USER: 0,
  DM_CHANNEL: 1,
  CATEGORY_CHANNEL: 2,
  GROUP: 3,
};

function typePriority(chatable) {
  if (chatable.type === "user") {
    return TYPE_PRIORITY.USER;
  }
  if (chatable.type === "group") {
    return TYPE_PRIORITY.GROUP;
  }
  if (chatable.model?.chatableType === "DirectMessage") {
    return TYPE_PRIORITY.DM_CHANNEL;
  }
  return TYPE_PRIORITY.CATEGORY_CHANNEL;
}

export function sortChatables(chatables) {
  return chatables.sort((a, b) => {
    // Primary: match quality (from server, lower is better)
    const matchA = a.matchQuality ?? MATCH_QUALITY_PARTIAL;
    const matchB = b.matchQuality ?? MATCH_QUALITY_PARTIAL;
    if (matchA !== matchB) {
      return matchA - matchB;
    }

    // Secondary: type priority (users > DM channels > category channels > groups)
    const typeA = typePriority(a);
    const typeB = typePriority(b);
    if (typeA !== typeB) {
      return typeA - typeB;
    }

    // Tertiary: enabled before disabled (applies to users and groups)
    if (a.enabled !== b.enabled) {
      return a.enabled ? -1 : 1;
    }

    return 0;
  });
}

export default class ChatablesLoader {
  @service chatChannelsManager;
  @service loadingSlider;

  constructor(context) {
    setOwner(this, getOwner(context));
  }

  @bind
  async search(
    term,
    options = {
      includeUsers: true,
      includeGroups: true,
      includeCategoryChannels: true,
      includeDirectMessageChannels: true,
      preloadChannels: false,
    }
  ) {
    this.request?.abort();

    if (!term && options.preloadChannels) {
      return this.#preloadedChannels();
    }

    if (!term) {
      return [];
    }

    try {
      this.loadingSlider.transitionStarted();
      this.request = ajax("/chat/api/chatables", {
        data: {
          term,
          include_users: options.includeUsers,
          include_category_channels: options.includeCategoryChannels,
          include_direct_message_channels: options.includeDirectMessageChannels,
          excluded_memberships_channel_id: options.excludedMembershipsChannelId,
        },
      });
      const results = await this.request;
      this.loadingSlider.transitionEnded();

      const chatables = [
        ...results.users,
        ...results.groups,
        ...results.direct_message_channels,
        ...results.category_channels,
      ].map((item) => {
        const chatable = ChatChatable.create(item);
        const channel = this.#findChannel(chatable);

        if (channel) {
          chatable.tracking = channel.tracking;
          chatable.unread_thread_count =
            channel.unreadThreadsCountSinceLastViewed;
        }

        return chatable;
      });

      return sortChatables(chatables).slice(0, MAX_RESULTS);
    } catch (e) {
      popupAjaxError(e);
    }
  }

  #preloadedChannels() {
    return this.chatChannelsManager.allChannels
      .map((channel) => {
        let chatable;
        if (channel.chatable?.users?.length === 1) {
          chatable = ChatChatable.createUser(channel.chatable.users[0]);
        } else {
          chatable = ChatChatable.createChannel(channel);
        }

        chatable.tracking = channel.tracking;
        chatable.unread_thread_count =
          channel.unreadThreadsCountSinceLastViewed;
        return chatable;
      })
      .filter(Boolean)
      .slice(0, MAX_RESULTS);
  }

  #findChannel(chatable) {
    if (!["user", "channel"].includes(chatable.type)) {
      return;
    }

    const { allChannels } = this.chatChannelsManager;
    if (chatable.type === "user") {
      return allChannels.find(
        ({ chatable: { users } }) =>
          users?.length === 1 && users[0].id === chatable.model.id
      );
    } else if (chatable.type === "channel") {
      return allChannels.find(({ id }) => id === chatable.model.id);
    }
  }
}
import Component from "@glimmer/component";
import ChannelTitle from "discourse/plugins/chat/discourse/components/channel-title";

export default class Channel extends Component {
  get tracking() {
    return this.args.item.tracking;
  }

  get isUrgent() {
    return this.args.item.model.isDirectMessageChannel
      ? this.hasUnreads || this.hasUrgent
      : this.hasUrgent;
  }

  get hasUnreads() {
    return this.tracking?.unreadCount > 0;
  }

  get hasUrgent() {
    return (
      this.tracking?.mentionCount > 0 ||
      this.tracking?.watchedThreadsUnreadCount > 0
    );
  }

  get hasUnreadThreads() {
    return this.args.item.unread_thread_count > 0;
  }

  get showIndicator() {
    return this.hasUnreads || this.hasUnreadThreads || this.hasUrgent;
  }

  <template>
    <div
      class="chat-message-creator__chatable -category-channel"
      data-disabled={{not @item.enabled}}
    >
      <ChannelTitle
        @channel={{@item.model}}
        @isUnread={{this.showIndicator}}
        @isUrgent={{this.isUrgent}}
      />
    </div>
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class ChatableGroup extends Component {
  @service siteSettings;

  group_with_too_many_members = i18n(
    "chat.new_message_modal.group_with_too_many_members",
    { membersCount: this.args.item.model.chat_enabled_user_count }
  );

  get isDisabled() {
    if (!this.args.membersCount) {
      return !this.args.item.enabled;
    }

    return (
      this.args.membersCount + this.args.item.model.chat_enabled_user_count >
      this.siteSettings.chat_max_direct_message_users
    );
  }

  <template>
    <div
      class="chat-message-creator__chatable -group"
      data-disabled={{this.isDisabled}}
    >
      <div class="chat-message-creator__group-icon">
        {{dIcon "user-group"}}
      </div>
      <div class="chat-message-creator__group-name">
        {{@item.model.name}}
      </div>

      {{#if this.isDisabled}}
        <span class="chat-message-creator__disabled-warning">
          {{this.group_with_too_many_members}}
        </span>
      {{/if}}
    </div>
  </template>
}
import dIcon from "discourse/ui-kit/helpers/d-icon";

const ListAction = <template>
  <div class="chat-message-creator__chatable -group">
    <div class="chat-message-creator__group-icon">
      {{dIcon @item.icon}}
    </div>
    <div class="chat-message-creator__group-name">
      {{@item.label}}
    </div>
  </div>
</template>;

export default ListAction;
import Component from "@glimmer/component";
import { service } from "@ember/service";
import { formatUsername } from "discourse/lib/utilities";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

export default class ChatUserDisplayName extends Component {
  @service siteSettings;

  get shouldPrioritizeNameInUx() {
    return !this.siteSettings.prioritize_username_in_ux;
  }

  get hasValidName() {
    return (
      this.siteSettings.enable_names &&
      this.args.user?.name &&
      this.args.user.name.trim().length > 0
    );
  }

  get formattedUsername() {
    return formatUsername(this.args.user?.username);
  }

  get shouldShowNameFirst() {
    return this.shouldPrioritizeNameInUx && this.hasValidName;
  }

  get shouldShowNameLast() {
    return !this.shouldPrioritizeNameInUx && this.hasValidName;
  }

  <template>
    <span class="chat-user-display-name">
      {{#if this.shouldShowNameFirst}}
        <span class="chat-user-display-name__name -first">{{@user.name}}</span>
      {{/if}}

      <span
        class={{dConcatClass
          "chat-user-display-name__username"
          (unless this.shouldShowNameFirst "-first")
        }}
      >
        {{this.formattedUsername}}
      </span>

      {{#if this.shouldShowNameLast}}
        <span class="chat-user-display-name__name">{{@user.name}}</span>
      {{/if}}
    </span>
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import { modifier } from "ember-modifier";
import userStatus from "discourse/helpers/user-status";
import DUserStatusMessage from "discourse/ui-kit/d-user-status-message";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";
import ChatUserAvatar from "discourse/plugins/chat/discourse/components/chat-user-avatar";
import ChatUserDisplayName from "discourse/plugins/chat/discourse/components/chat-user-display-name";

export default class ChatableUser extends Component {
  @service currentUser;

  disabledUserLabel = i18n("chat.new_message_modal.disabled_user");

  trackUserStatus = modifier((element, [user]) => {
    user.statusManager.trackStatus();

    return () => {
      user.statusManager.stopTrackingStatus();
    };
  });

  get showIndicator() {
    return this.isUrgent || this.isUnread;
  }

  get isUrgent() {
    return (
      this.args.item.tracking?.unreadCount > 0 ||
      this.args.item.tracking?.mentionCount > 0 ||
      this.args.item.tracking?.watchedThreadsUnreadCount > 0
    );
  }

  get isUnread() {
    return this.args.item.unread_thread_count > 0;
  }

  <template>
    <div
      class="chat-message-creator__chatable -user"
      data-disabled={{not @item.enabled}}
    >
      <ChatUserAvatar @interactive={{false}} @user={{@item.model}} />
      <ChatUserDisplayName @user={{@item.model}} />

      {{#if this.showIndicator}}
        <div
          class={{dConcatClass
            "unread-indicator d-new-indicator"
            (if this.isUrgent "-urgent")
          }}
        ></div>
      {{/if}}

      {{userStatus @item.model currentUser=this.currentUser}}

      <div class="user-status" {{this.trackUserStatus @item.model}}>
        <DUserStatusMessage
          @showDescription={{true}}
          @status={{@item.model.status}}
        />
      </div>

      {{#unless @item.enabled}}
        <span class="chat-message-creator__disabled-warning">
          {{this.disabledUserLabel}}
        </span>
      {{/unless}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";
import Channel from "./channel.gjs";
import Group from "./group.gjs";
import ListAction from "./list-action.gjs";
import User from "./user.gjs";

export default class List extends Component {
  cantAddMoreMembersLabel = i18n(
    "chat.new_message_modal.cant_add_more_members"
  );

  componentForItem(type) {
    switch (type) {
      case "list-action":
        return ListAction;
      case "user":
        return User;
      case "group":
        return Group;
      case "channel":
        return Channel;
    }
  }

  @action
  handleEnter(item, event) {
    if (event.key !== "Enter") {
      return;
    }

    if (event.shiftKey && this.args.onShiftSelect) {
      this.args.onShiftSelect?.(item);
    } else {
      this.args.onSelect?.(item);
    }
  }

  @action
  handleClick(item, event) {
    if (event.shiftKey && this.args.onShiftSelect) {
      this.args.onShiftSelect?.(item);
    } else {
      this.args.onSelect?.(item);
    }
  }

  <template>
    {{#if @items}}
      <div class="chat-message-creator__list-container">
        {{#if @maxReached}}
          <div
            class="chat-message-creator__warning-max-members"
          >{{this.cantAddMoreMembersLabel}}</div>
        {{else}}
          <ul class="chat-message-creator__list">
            {{#each @items as |item|}}
              <li
                class={{dConcatClass
                  "chat-message-creator__list-item"
                  (if
                    (eq item.identifier @highlightedItem.identifier)
                    "-highlighted"
                  )
                }}
                data-identifier={{item.identifier}}
                id={{item.id}}
                role="button"
                tabindex="0"
                {{on "click" (fn this.handleClick item)}}
                {{on "keypress" (fn this.handleEnter item)}}
                {{on "mousemove" (fn @onHighlight item)}}
                {{on "mouseleave" (fn @onHighlight null)}}
              >
                {{component
                  (this.componentForItem item.type)
                  membersCount=@membersCount
                  item=item
                }}
              </li>
            {{/each}}
          </ul>
        {{/if}}
      </div>
    {{/if}}
  </template>
}
export function getNext(list, current = null) {
  if (list.length === 0) {
    return null;
  }

  list = list.filter((item) => item.enabled);

  if (current?.identifier) {
    const currentIndex = list.findIndex(
      (item) => item.identifier === current?.identifier
    );

    if (currentIndex < list.length - 1) {
      return list[currentIndex + 1];
    } else {
      return list[0];
    }
  } else {
    return list[0];
  }
}

export function getPrevious(list, current = null) {
  if (list.length === 0) {
    return null;
  }

  list = list.filter((item) => item.enabled);

  if (current?.identifier) {
    const currentIndex = list.findIndex(
      (item) => item.identifier === current?.identifier
    );

    if (currentIndex > 0) {
      return list[currentIndex - 1];
    } else {
      return list.at(-1);
    }
  } else {
    return list.at(-1);
  }
}
import Component from "@glimmer/component";
import { modifier } from "ember-modifier";
import { getNext, getPrevious } from "./lib/iterate-list.js";

export default class ListHandler extends Component {
  handleKeydown = modifier((element) => {
    const handler = (event) => {
      if (event.key === "ArrowDown") {
        event.preventDefault();
        event.stopPropagation();

        this.args.onHighlight(
          getNext(this.args.items, this.args.highlightedItem)
        );
      } else if (event.key === "ArrowUp") {
        event.preventDefault();
        event.stopPropagation();

        this.args.onHighlight(
          getPrevious(this.args.items, this.args.highlightedItem)
        );
      } else if (event.key === "Enter" && this.args.highlightedItem) {
        event.preventDefault();
        event.stopPropagation();

        if (event.shiftKey && this.args.onShifSelect) {
          this.args.onShifSelect(this.args.highlightedItem);
        } else {
          this.args.onSelect(this.args.highlightedItem);
        }
      }
    };

    element.addEventListener("keydown", handler);

    return () => {
      element.removeEventListener("keydown", handler);
    };
  });

  <template>
    <span style="display: contents" ...attributes {{this.handleKeydown}}>
      {{yield}}
    </span>
  </template>
}
import { fn } from "@ember/helper";
import DButton from "discourse/ui-kit/d-button";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import ChatUserAvatar from "discourse/plugins/chat/discourse/components/chat-user-avatar";

const Member = <template>
  <DButton
    class={{dConcatClass
      "chat-message-creator__member btn-default btn-small"
      (if @highlighted "-highlighted")
    }}
    @action={{fn @onSelect @member}}
  >
    {{#if (eq @member.type "user")}}
      <ChatUserAvatar
        @interactive={{false}}
        @showPresence={{false}}
        @user={{@member.model}}
      />
      <span class="chat-message-creator__member-username">
        {{@member.model.username}}
      </span>
    {{else if (eq @member.type "group")}}
      <div class="chat-message-creator__group-icon">
        {{dIcon "user-group"}}
      </div>
      <span class="chat-message-creator__member-group">
        {{@member.model.name}}
      </span>
    {{/if}}

    {{dIcon "xmark"}}
  </DButton>
</template>;

export default Member;
import Component from "@glimmer/component";
import { Input } from "@ember/component";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
import { getNext, getPrevious } from "./lib/iterate-list.js";
import Member from "./member.gjs";

export default class Members extends Component {
  addMoreMembersLabel = i18n("chat.new_message_modal.user_search_placeholder");

  @action
  onFilter() {
    this.args.onFilter(...arguments);
  }

  @action
  registerFocusFilterAction(element) {
    this.args.registerFocusFilterAction(() => element.focus());
  }

  @action
  handleKeypress(event) {
    if (event.key === "Backspace" && event.target.value === "") {
      event.preventDefault();
      event.stopPropagation();

      if (!this.args.highlightedMember) {
        this.args.onHighlightMember(this.args.members.at(-1));
      } else {
        this.args.onSelectMember(this.args.highlightedMember);
      }

      return;
    }

    if (event.key === "ArrowLeft" && event.target.value === "") {
      event.preventDefault();
      event.stopPropagation();

      this.args.onHighlightMember(
        getPrevious(this.args.members, this.args.highlightedMember)
      );

      return;
    }
    if (event.key === "ArrowRight" && event.target.value === "") {
      event.preventDefault();
      event.stopPropagation();

      this.args.onHighlightMember(
        getNext(this.args.members, this.args.highlightedMember)
      );

      return;
    }

    if (event.key === "Enter" && this.args.highlightedMember) {
      event.preventDefault();
      event.stopPropagation();

      this.args.onSelectMember(this.args.highlightedMember);

      return;
    }

    this.highlightedMember = null;
  }

  <template>
    <div class="chat-message-creator__members-container">
      <div class="chat-message-creator__members">
        {{dIcon "magnifying-glass"}}

        {{#each @members as |member|}}
          <Member
            @highlighted={{eq member @highlightedMember}}
            @member={{member}}
            @onSelect={{@onSelectMember}}
          />
        {{/each}}

        <Input
          autofocus={{true}}
          class="chat-message-creator__members-input"
          placeholder={{this.addMoreMembersLabel}}
          @value={{@filter}}
          {{on "input" this.onFilter}}
          {{on "keydown" this.handleKeypress}}
          {{didInsert this.registerFocusFilterAction}}
        />
      </div>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import discourseDebounce from "discourse/lib/debounce";
import { INPUT_DELAY } from "discourse/lib/environment";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";
import ChatablesLoader from "./lib/chatables-loader.js";
import List from "./list.gjs";
import ListHandler from "./list-handler.gjs";
import Members from "./members.gjs";

export default class MembersSelector extends Component {
  @service siteSettings;

  @tracked chatables = [];
  @tracked filter = "";
  @tracked highlightedMember;
  @tracked highlightedChatable;

  placeholder = i18n("chat.direct_message_creator.group_name");

  get items() {
    return this.chatables.filter(
      (c) => !this.selectedIdentifiers.includes(c.identifier)
    );
  }

  get selectedIdentifiers() {
    return this.args.members.map((member) => member.identifier);
  }

  @action
  highlightMember(member) {
    this.highlightedMember = member;
  }

  @action
  highlightChatable(chatable) {
    this.highlightedChatable = chatable;
  }

  @action
  selectChatable(chatable) {
    if (!chatable.enabled) {
      return;
    }

    const chatableMembers =
      chatable.type === "group" ? chatable.model.chat_enabled_user_count : 1;

    if (
      this.args.membersCount + chatableMembers >
      this.siteSettings.chat_max_direct_message_users
    ) {
      return;
    }

    if (this.selectedIdentifiers.includes(chatable.identifier)) {
      this.unselectMember(chatable);
    } else {
      this.args.onChange?.([...this.args.members, chatable]);
      this.highlightedChatable = this.items[0];
    }

    this.filter = "";
    this.focusFilterAction?.();
    this.highlightedMember = null;
  }

  @action
  registerFocusFilterAction(actionFn) {
    this.focusFilterAction = actionFn;
  }

  @action
  onFilter(event) {
    this.searchHandler = discourseDebounce(
      this,
      this.fetch,
      event.target.value,
      INPUT_DELAY
    );
  }

  @action
  async fetch(term) {
    this.highlightedMember = null;

    const loader = new ChatablesLoader(this);
    this.chatables = await loader.search(term, {
      includeCategoryChannels: false,
      includeDirectMessageChannels: false,
      excludedMembershipsChannelId: this.args.channel?.id,
    });

    this.highlightedChatable = this.items[0];
  }

  @action
  unselectMember(removedMember) {
    this.args.onChange?.(
      this.args.members.filter((member) => member !== removedMember)
    );
    this.highlightedMember = null;
    this.highlightedChatable = this.items[0];
    this.focusFilterAction?.();
  }

  <template>
    <ListHandler
      @highlightedItem={{this.highlightedChatable}}
      @items={{this.items}}
      @onHighlight={{this.highlightChatable}}
      @onSelect={{this.selectChatable}}
    >
      <div class="chat-message-creator__add-members-header-container">
        <div class="chat-message-creator__add-members-header">
          <Members
            @filter={{this.filter}}
            @highlightedMember={{this.highlightedMember}}
            @members={{@members}}
            @onFilter={{this.onFilter}}
            @onHighlightMember={{this.highlightMember}}
            @onSelectMember={{this.unselectMember}}
            @registerFocusFilterAction={{this.registerFocusFilterAction}}
          />

          <DButton
            class="btn-flat chat-message-creator__add-members__close-btn"
            @action={{@cancel}}
            @icon="xmark"
          />
        </div>
      </div>

      <List
        @highlightedItem={{this.highlightedChatable}}
        @items={{this.items}}
        @maxReached={{@maxReached}}
        @membersCount={{@membersCount}}
        @onHighlight={{this.highlightChatable}}
        @onSelect={{this.selectChatable}}
      />

    </ListHandler>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";
import MembersCount from "./members-count.gjs";
import MembersSelector from "./members-selector.gjs";

export default class AddMembers extends Component {
  @service chatApi;
  @service router;
  @service toasts;
  @service siteSettings;
  @service loadingSlider;

  get membersCount() {
    const userCount = this.args.members?.reduce((acc, member) => {
      if (member.type === "group") {
        return acc + member.model.chat_enabled_user_count;
      } else {
        return acc + 1;
      }
    }, 0);
    return userCount + (this.args.channel?.membershipsCount ?? 0);
  }

  get maxMembers() {
    return this.siteSettings.chat_max_direct_message_users;
  }

  @action
  async saveGroupMembers() {
    try {
      this.loadingSlider.transitionStarted();

      const usernames = this.args.members
        .filter((member) => member.type === "user")
        .map((member) => member.model.username);

      const groups = this.args.members
        .filter((member) => member.type === "group")
        .map((member) => member.model.name);

      await this.chatApi.addMembersToChannel(this.args.channel.id, {
        usernames,
        groups,
      });

      this.toasts.success({ data: { message: i18n("saved") } });
      this.router.transitionTo(
        "chat.channel",
        ...this.args.channel.routeModels
      );
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.loadingSlider.transitionEnded();
    }
  }

  <template>
    <div class="chat-message-creator__add-members-container">
      <div class="chat-message-creator__add-members">
        <MembersCount @count={{this.membersCount}} @max={{this.maxMembers}} />

        <MembersSelector
          @cancel={{@cancel}}
          @channel={{@channel}}
          @close={{@close}}
          @maxReached={{gte this.membersCount this.maxMembers}}
          @members={{@members}}
          @membersCount={{this.membersCount}}
          @onChange={{@onChangeMembers}}
        />

        {{#if @members.length}}
          <div class="chat-message-creator__add-members-footer-container">
            <div class="chat-message-creator__add-members-footer">
              <DButton class="btn-flat" @action={{@cancel}} @label="cancel" />

              <DButton
                class="btn-primary add-to-channel"
                @action={{this.saveGroupMembers}}
                @label="chat.direct_message_creator.add_to_channel"
              />
            </div>
          </div>
        {{/if}}
      </div>
    </div>
  </template>
}
