import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import { service } from "@ember/service";
import { popupAjaxError } from "discourse/lib/ajax-error";
import discourseDebounce from "discourse/lib/debounce";
import { INPUT_DELAY } from "discourse/lib/environment";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";
import { MODES } from "./constants.js";
import ChatablesLoader from "./lib/chatables-loader.js";
import List from "./list.gjs";
import ListHandler from "./list-handler.gjs";
import SearchInput from "./search-input.gjs";

export default class ChatMessageCreatorSearch extends Component {
  @service chat;
  @service chatGuardian;
  @service router;

  @tracked chatables = [];
  @tracked highlightedChatable;
  @tracked term;

  get items() {
    const items = [];

    if (!this.term?.length && this.chatGuardian.canUseGroupChat()) {
      items.push({
        identifier: "new-group",
        type: "list-action",
        label: i18n("chat.new_message_modal.new_group_chat"),
        enabled: true,
        icon: "user-group",
        id: "new-group-chat",
      });
    }

    return [...items, ...this.chatables];
  }

  @action
  prefillAddMembers(item) {
    this.args.onChangeMode(MODES.new_group, [item]);
  }

  @action
  highlightChatable(chatable) {
    this.highlightedChatable = chatable;
  }

  @action
  async selectChatable(item) {
    switch (item.type) {
      case "list-action":
        this.args.onChangeMode(MODES.new_group);
        break;
      case "user":
        if (!item.enabled) {
          return;
        }

        await this.startOneToOneChannel(item.model.username);
        break;
      case "group":
        if (!item.enabled) {
          return;
        }

        this.args.onChangeMode(MODES.new_group, [item]);
        break;
      default:
        this.router.transitionTo("chat.channel", ...item.model.routeModels);
        this.args.close();
        break;
    }
  }

  @action
  onFilter(event) {
    this.chatables = [];
    this.term = event?.target?.value;

    this.searchHandler = discourseDebounce(
      this,
      this.fetch,
      event.target.value,
      INPUT_DELAY
    );
  }

  @action
  async fetch() {
    const loader = new ChatablesLoader(this);
    this.chatables = await loader.search(this.term, {
      preloadChannels: !this.term,
    });

    this.highlightedChatable = this.items[0];
  }

  async startOneToOneChannel(username) {
    try {
      const channel = await this.chat.upsertDmChannel({
        usernames: [username],
      });

      if (!channel) {
        return;
      }

      this.args.close?.();
      this.router.transitionTo("chat.channel", ...channel.routeModels);
    } catch (error) {
      popupAjaxError(error);
    }
  }

  async startGroupChannel(group) {
    try {
      const channel = await this.chat.upsertDmChannel({ groups: [group] });

      if (!channel) {
        return;
      }

      this.args.close?.();
      this.router.transitionTo("chat.channel", ...channel.routeModels);
    } catch (error) {
      popupAjaxError(error);
    }
  }

  <template>
    <ListHandler
      @highlightedItem={{this.highlightedChatable}}
      @items={{this.items}}
      @onHighlight={{this.highlightChatable}}
      @onSelect={{this.selectChatable}}
      @onShifSelect={{this.prefillAddMembers}}
    >
      <div class="chat-message-creator__search-container">
        <div class="chat-message-creator__search">
          <div
            class="chat-message-creator__section"
            {{didInsert (fn this.fetch null)}}
          >
            <SearchInput @filter={{this.term}} @onFilter={{this.onFilter}} />

            <DButton
              class="btn-flat chat-message-creator__search-input__cancel-button"
              @action={{@close}}
              @icon="xmark"
            />
          </div>

          <List
            @highlightedItem={{this.highlightedChatable}}
            @items={{this.items}}
            @onHighlight={{this.highlightChatable}}
            @onSelect={{this.selectChatable}}
            @onShiftSelect={{this.prefillAddMembers}}
          />
        </div>
      </div>
    </ListHandler>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { autoTrackedArray } from "discourse/lib/tracked-tools";
import AddMembers from "./add-members.gjs";
import { MODES } from "./constants.js";
import NewGroup from "./new-group.gjs";
import Search from "./search.gjs";

export default class ChatMessageCreator extends Component {
  @tracked mode = this.args.initialMode ?? MODES.search;
  @autoTrackedArray members = [];

  get componentForMode() {
    switch (this.args.mode ?? this.mode) {
      case MODES.search:
        return Search;
      case MODES.new_group:
        return NewGroup;
      case MODES.add_members:
        return AddMembers;
    }
  }

  @action
  changeMode(mode, members = []) {
    this.mode = mode;
    this.changeMembers(members);
  }

  @action
  changeMembers(members) {
    this.members = members;
  }

  @action
  cancelAction() {
    return this.args.onCancel?.() || this.changeMode(MODES.search);
  }

  <template>
    <div class="chat-message-creator-container">
      <div class="chat-message-creator">
        <this.componentForMode
          @cancel={{this.cancelAction}}
          @channel={{@channel}}
          @close={{@onClose}}
          @members={{this.members}}
          @onChangeMembers={{this.changeMembers}}
          @onChangeMode={{this.changeMode}}
        />
      </div>
    </div>
  </template>
}
