import lazyHash from "discourse/helpers/lazy-hash";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dEmoji from "discourse/ui-kit/helpers/d-emoji";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import dReplaceEmoji from "discourse/ui-kit/helpers/d-replace-emoji";
import { i18n } from "discourse-i18n";
import ToggleChannelMembershipButton from "./toggle-channel-membership-button.gjs";

export default <template>
  {{#if @channel}}
    <div
      class={{dConcatClass
        "chat-channel-card"
        (if @channel.isClosed "--closed")
        (if @channel.isArchived "--archived")
      }}
      data-channel-id={{@channel.id}}
      style={{trustHTML
        (concat "--chat-channel-card-border: #" @channel.chatable.color)
      }}
    >
      <div class="chat-channel-card__header">
        <LinkTo
          class="chat-channel-card__name-container"
          @models={{@channel.routeModels}}
          @route="chat.channel"
        >
          <span class="chat-channel-card__name">
            {{#if @channel.emoji}}
              {{dEmoji @channel.emoji}}
            {{/if}}
            {{dReplaceEmoji @channel.title}}
          </span>
          {{#if @channel.chatable.read_restricted}}
            {{dIcon "lock" class="chat-channel-card__read-restricted"}}
          {{/if}}
          {{#if @channel.currentUserMembership.muted}}
            <span
              aria-label={{i18n "chat.muted"}}
              class="chat-channel-card__muted"
              title={{i18n "chat.muted"}}
            >{{dIcon "d-muted"}}</span>
          {{/if}}
        </LinkTo>
      </div>

      <div class="chat-channel-card__cta">
        <PluginOutlet
          @defaultGlimmer={{true}}
          @name="chat-channel-card-cta"
          @outletArgs={{lazyHash channel=@channel}}
        >
          {{#if @channel.isFollowing}}
            <ToggleChannelMembershipButton
              @channel={{@channel}}
              @options={{hash
                leaveClass="btn-default btn-small chat-channel-card__leave-btn"
                labelType="short"
              }}
            />

          {{else if @channel.isJoinable}}
            <ToggleChannelMembershipButton
              @channel={{@channel}}
              @options={{hash
                joinClass="btn-primary btn-small chat-channel-card__join-btn"
                labelType="short"
              }}
            />
          {{/if}}
        </PluginOutlet>
      </div>

      {{#if (gt @channel.membershipsCount 0)}}
        <LinkTo
          class="chat-channel-card__members"
          @models={{@channel.routeModels}}
          @route="chat.channel.info.members"
        >
          {{i18n
            "chat.channel.memberships_count"
            count=@channel.membershipsCount
          }}
        </LinkTo>
      {{/if}}

      {{#if @channel.description}}
        <div class="chat-channel-card__description">
          {{dReplaceEmoji @channel.description}}
        </div>
      {{/if}}
    </div>
  {{/if}}
</template>
import Component from "@glimmer/component";
import { cached, tracked } from "@glimmer/tracking";
import { concat } from "@ember/helper";
import { action } from "@ember/object";
import { LinkTo } from "@ember/routing";
import { service } from "@ember/service";
import discourseDebounce from "discourse/lib/debounce";
import { INPUT_DELAY } from "discourse/lib/environment";
import DEmptyState from "discourse/ui-kit/d-empty-state";
import DFilterControls from "discourse/ui-kit/d-filter-controls";
import { i18n } from "discourse-i18n";
import List from "discourse/plugins/chat/discourse/components/chat/list";
import ChatModalNewMessage from "discourse/plugins/chat/discourse/components/chat/modal/new-message";
import ChatChannelCard from "discourse/plugins/chat/discourse/components/chat-channel-card";

const ARCHIVED = "archived";
const ALL = "all";
const OPEN = "open";
const CLOSED = "closed";
const TABS = [ALL, OPEN, CLOSED, ARCHIVED];

export default class BrowseChannels extends Component {
  @service chatApi;
  @service modal;
  @service siteSettings;

  @tracked filter = "";
  @tracked selectedJoinedFilter = "all";

  get currentTab() {
    return this.args.currentTab ?? ALL;
  }

  get joinedFilters() {
    return [
      { label: i18n("chat.browse.filter_joined_all"), value: "all" },
      { label: i18n("chat.browse.filter_joined_joined"), value: "joined" },
      {
        label: i18n("chat.browse.filter_joined_not_joined"),
        value: "not-joined",
      },
    ];
  }

  @cached
  get channelsCollection() {
    return this.chatApi.channels({
      filter: this.filter,
      status: this.currentTab,
    });
  }

  get tabs() {
    if (this.siteSettings.chat_allow_archiving_channels) {
      return TABS;
    } else {
      return TABS.filter((item) => item !== ARCHIVED);
    }
  }

  @action
  setJoinedFilter(value) {
    this.selectedJoinedFilter = value;
  }

  @action
  filterChannelsByJoined(listItems) {
    if (this.selectedJoinedFilter === "joined") {
      return listItems.filter((channel) => channel.isFollowing);
    } else if (this.selectedJoinedFilter === "not-joined") {
      return listItems.filter((channel) => !channel.isFollowing);
    } else {
      return listItems;
    }
  }

  @action
  showChatNewMessageModal() {
    this.modal.show(ChatModalNewMessage);
  }

  @action
  setFilter(event) {
    discourseDebounce(
      this,
      this.debouncedSetFilter,
      event.target.value,
      INPUT_DELAY
    );
  }

  @action
  debouncedSetFilter(value) {
    this.filter = value;
  }

  <template>
    <div class="chat-browse-view">
      <div class="chat-browse-view__actions">
        <nav>
          <ul class="nav-pills chat-browse-view__filters">
            {{#each this.tabs as |tab|}}
              <li class={{concat "chat-browse-view__filter -" tab}}>
                <LinkTo
                  class={{concat "chat-browse-view__filter-link -" tab}}
                  @current-when={{eq tab this.currentTab}}
                  @route={{concat "chat.browse." tab}}
                >
                  {{i18n (concat "chat.browse.filter_" tab)}}
                </LinkTo>
              </li>
            {{/each}}
          </ul>
        </nav>

        <DFilterControls
          @array={{this.channelsCollection.items}}
          @dropdownOptions={{this.joinedFilters}}
          @dropdownValue={{this.selectedJoinedFilter}}
          @inputPlaceholder={{i18n "chat.browse.filter_input_placeholder"}}
          @loading={{this.channelsCollection.loading}}
          @onDropdownFilterChange={{this.setJoinedFilter}}
          @onTextFilterChange={{this.setFilter}}
          @showNoResults={{false}}
          @showResetButton={{false}}
        />
      </div>

      <div class="chat-browse-view__content_wrapper">
        <div class="chat-browse-view__content">
          <List
            class="chat-browse-view__cards"
            @collection={{this.channelsCollection}}
            @filterFn={{this.filterChannelsByJoined}}
            as |list|
          >
            <list.Item as |channel|>
              <ChatChannelCard @channel={{channel}} />
            </list.Item>

            <list.EmptyState>
              <DEmptyState
                @body={{i18n "chat.empty_state.direct_message"}}
                @ctaAction={{this.showChatNewMessageModal}}
                @ctaLabel={{i18n "chat.empty_state.direct_message_cta"}}
                @title={{i18n "chat.empty_state.title"}}
              />
            </list.EmptyState>
          </List>
        </div>
      </div>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DButton from "discourse/ui-kit/d-button";

export default class ChatChannelListFilterToggle extends Component {
  @service chatChannelListPreferences;

  get bypassed() {
    return this.chatChannelListPreferences.isFilterBypassedFor(this.section);
  }

  get disabled() {
    return this.chatChannelListPreferences.isSavingFilterFor(this.section);
  }

  get section() {
    return this.args.section ?? "channels";
  }

  get visible() {
    return !this.chatChannelListPreferences.isDefaultFilterFor(this.section);
  }

  @action
  toggle() {
    this.chatChannelListPreferences.toggleFilter(this.section);
  }

  <template>
    {{#if this.visible}}
      <DButton
        class="btn-transparent chat-channel-list-filter-toggle title-action"
        ...attributes
        @action={{this.toggle}}
        @disabled={{this.disabled}}
        @icon={{if this.bypassed "filter" "filter-circle-xmark"}}
        @title={{if
          this.bypassed
          "chat.channel_list.apply_filters"
          "chat.channel_list.empty.show_all"
        }}
      />
    {{/if}}
  </template>
}
/**
 * Options exposed by the shared chat channel list menu for each sidebar /
 * drawer / mobile section. Used by the cover sidebar section headers and by
 * the non-sidebar list headers so both stay in sync.
 */
export const CHANNEL_LIST_SECTION_OPTIONS = {
  channels: {
    showCreateChannel: true,
    showBrowse: true,
    showFilter: true,
    showSort: true,
  },
  starred: { showFilter: true, showSort: true },
  dms: { showNewMessage: true, showFilter: true, showSort: true },
};
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn, hash } from "@ember/helper";
import { action } from "@ember/object";
import { cancel } from "@ember/runloop";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import Form from "discourse/components/form";
import { ajax } from "discourse/lib/ajax";
import { extractError } from "discourse/lib/ajax-error";
import discourseDebounce from "discourse/lib/debounce";
import { escapeExpression } from "discourse/lib/utilities";
import Category from "discourse/models/category";
import CategoryChooser from "discourse/select-kit/components/category-chooser";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import I18n, { i18n } from "discourse-i18n";

const DEFAULT_HINT = trustHTML(
  i18n("chat.create_channel.choose_category.default_hint", {
    link: "/categories",
    category: "category",
  })
);

export default class ChatModalCreateChannel extends Component {
  @service dialog;
  @service chatChannelsManager;
  @service chatApi;
  @service router;
  @service siteSettings;

  @tracked flash;
  @tracked category;
  @tracked autoGeneratedSlug = "";
  @tracked categoryPermissionsHint = DEFAULT_HINT;
  @tracked autoJoinWarning = "";
  @tracked loadingPermissionHint = false;

  formApi;
  formData = {
    name: "",
    slug: "",
    description: "",
    chatable_id: null,
    emoji: null,
    auto_join_users: false,
    threading_enabled: false,
  };
  #generateSlugHandler = null;

  willDestroy() {
    super.willDestroy(...arguments);
    cancel(this.#generateSlugHandler);
  }

  get autoJoinAvailable() {
    return this.siteSettings.max_chat_auto_joined_users > 0;
  }

  get categoryName() {
    return this.category ? escapeExpression(this.category.name) : null;
  }

  @action
  registerApi(api) {
    this.formApi = api;
  }

  @action
  submit() {
    this.formApi.submit();
  }

  @action
  onCategoryChange(categoryId, { set }) {
    const category = categoryId ? Category.findById(categoryId) : null;
    set("chatable_id", categoryId);
    this.category = category;
    this.#updatePermissionsHint(category);

    const name = this.formApi.get("name") || category?.name || "";
    set("name", name);
    this.#debouncedGenerateSlug(name);
  }

  @action
  onNameChange(name, { set }) {
    set("name", name);
    this.#debouncedGenerateSlug(name);
  }

  @action
  onSubmit(data) {
    const payload = {
      name: data.name,
      slug: data.slug || this.autoGeneratedSlug,
      description: data.description,
      chatable_id: data.chatable_id,
      auto_join_users: data.auto_join_users,
      threading_enabled: data.threading_enabled,
      emoji: data.emoji,
    };

    if (payload.auto_join_users) {
      this.dialog.yesNoConfirm({
        message: this.autoJoinWarning,
        didConfirm: () => this.#createChannel(payload),
      });
    } else {
      this.#createChannel(payload);
    }
  }

  async #createChannel(data) {
    try {
      const channel = await this.chatApi.createChannel(data);

      this.args.closeModal();
      this.chatChannelsManager.follow(channel);
      this.router.transitionTo("chat.channel", ...channel.routeModels);
    } catch (e) {
      this.flash = extractError(e);
    }
  }

  #buildCategorySlug(category) {
    const parent = category.parentCategory;

    if (parent) {
      return `${this.#buildCategorySlug(parent)}/${category.slug}`;
    } else {
      return category.slug;
    }
  }

  #updateAutoJoinConfirmWarning(category, catPermissions) {
    const allowedGroups = catPermissions.allowed_groups;
    let warning;

    if (catPermissions.private) {
      switch (allowedGroups.length) {
        case 1:
          warning = i18n(
            "chat.create_channel.auto_join_users.warning_1_group",
            {
              count: catPermissions.members_count,
              group: escapeExpression(allowedGroups[0]),
            }
          );
          break;
        case 2:
          warning = i18n(
            "chat.create_channel.auto_join_users.warning_2_groups",
            {
              count: catPermissions.members_count,
              group1: escapeExpression(allowedGroups[0]),
              group2: escapeExpression(allowedGroups[1]),
            }
          );
          break;
        default:
          warning = I18n.messageFormat(
            "chat.create_channel.auto_join_users.warning_multiple_groups_MF",
            {
              groupCount: allowedGroups.length - 1,
              userCount: catPermissions.members_count,
              groupName: escapeExpression(allowedGroups[0]),
            }
          );
          break;
      }
    } else {
      warning = i18n(
        "chat.create_channel.auto_join_users.public_category_warning",
        {
          category: escapeExpression(category.name),
        }
      );
    }

    this.autoJoinWarning = warning;
  }

  #updatePermissionsHint(category) {
    if (category) {
      const fullSlug = this.#buildCategorySlug(category);

      this.loadingPermissionHint = true;

      return this.chatApi
        .categoryPermissions(category.id)
        .then((catPermissions) => {
          this.#updateAutoJoinConfirmWarning(category, catPermissions);
          const allowedGroups = catPermissions.allowed_groups;
          const settingLink = `/c/${escapeExpression(fullSlug)}/edit/security`;
          let hint;

          switch (allowedGroups.length) {
            case 1:
              hint = i18n("chat.create_channel.choose_category.hint_1_group", {
                settingLink,
                group: escapeExpression(allowedGroups[0]),
              });
              break;
            case 2:
              hint = i18n("chat.create_channel.choose_category.hint_2_groups", {
                settingLink,
                group1: escapeExpression(allowedGroups[0]),
                group2: escapeExpression(allowedGroups[1]),
              });
              break;
            default:
              hint = i18n(
                "chat.create_channel.choose_category.hint_multiple_groups",
                {
                  settingLink,
                  group: escapeExpression(allowedGroups[0]),
                  count: allowedGroups.length - 1,
                }
              );
              break;
          }

          this.categoryPermissionsHint = trustHTML(hint);
        })
        .finally(() => {
          this.loadingPermissionHint = false;
        });
    } else {
      this.categoryPermissionsHint = DEFAULT_HINT;
      this.autoJoinWarning = "";
    }
  }

  // intentionally not showing AJAX error for this, we will autogenerate
  // the slug server-side if they leave it blank
  #generateSlug(name) {
    return ajax("/slugs.json", { type: "POST", data: { name } }).then(
      (response) => {
        this.autoGeneratedSlug = response.slug;
      }
    );
  }

  #debouncedGenerateSlug(name) {
    cancel(this.#generateSlugHandler);
    this.autoGeneratedSlug = "";

    if (!name) {
      return;
    }

    this.#generateSlugHandler = discourseDebounce(
      this,
      this.#generateSlug,
      name,
      300
    );
  }

  <template>
    <DModal
      class="chat-modal-create-channel"
      @closeModal={{@closeModal}}
      @flash={{this.flash}}
      @inline={{@inline}}
      @title={{i18n "chat.create_channel.title"}}
    >
      <:body>
        <Form
          class="chat-modal-create-channel__form"
          @data={{this.formData}}
          @onRegisterApi={{this.registerApi}}
          @onSubmit={{this.onSubmit}}
          as |form|
        >
          <form.Field
            @format="full"
            @name="name"
            @onSet={{this.onNameChange}}
            @title={{i18n "chat.create_channel.name"}}
            @type="input"
            @validation="required"
            as |field|
          >
            <field.Control />
          </form.Field>

          <form.Field
            @format="full"
            @name="slug"
            @title={{i18n "chat.create_channel.slug"}}
            @tooltip={{i18n
              "chat.channel_edit_name_slug_modal.slug_description"
            }}
            @type="input"
            as |field|
          >
            <field.Control placeholder={{this.autoGeneratedSlug}} />
          </form.Field>

          <form.Field
            @format="full"
            @name="description"
            @title={{i18n "chat.create_channel.description"}}
            @type="input"
            as |field|
          >
            <field.Control />
          </form.Field>

          <form.Field
            @format="full"
            @name="chatable_id"
            @onSet={{this.onCategoryChange}}
            @title={{i18n "chat.create_channel.choose_category.label"}}
            @type="custom"
            @validation="required"
            as |field|
          >
            <field.Control>
              <CategoryChooser
                @onChange={{field.set}}
                @options={{hash
                  none="chat.create_channel.choose_category.none"
                }}
                @value={{field.value}}
              />

              {{#if this.categoryPermissionsHint}}
                <div
                  class={{dConcatClass
                    "chat-modal-create-channel__hint"
                    (if this.loadingPermissionHint "loading-permissions")
                  }}
                >
                  {{this.categoryPermissionsHint}}
                </div>
              {{/if}}
            </field.Control>
          </form.Field>

          {{#if this.siteSettings.enable_emoji}}
            <form.Field
              @name="emoji"
              @title={{i18n "chat.create_channel.emoji.label"}}
              @type="emoji"
              as |field|
            >
              <field.Control @context="channel-emoji" />

              <DButton
                class="btn-flat edit-channel-clear-emoji"
                @action={{fn field.set null}}
                @disabled={{not field.value}}
                @label="chat.create_channel.emoji.reset"
              />
            </form.Field>
          {{/if}}

          {{#if this.autoJoinAvailable}}
            <form.Field
              @format="full"
              @name="auto_join_users"
              @title={{i18n "chat.settings.auto_join_users_label"}}
              @type="checkbox"
              as |field|
            >
              <field.Control>
                {{#if this.categoryName}}
                  {{i18n
                    "chat.settings.auto_join_users_info"
                    category=this.categoryName
                  }}
                {{else}}
                  {{i18n "chat.settings.auto_join_users_info_no_category"}}
                {{/if}}
              </field.Control>
            </form.Field>
          {{/if}}

          <form.Field
            @format="full"
            @name="threading_enabled"
            @title={{i18n "chat.create_channel.threading.label"}}
            @type="checkbox"
            as |field|
          >
            <field.Control>
              {{i18n "chat.settings.channel_threading_description"}}
            </field.Control>
          </form.Field>
        </Form>
      </:body>
      <:footer>
        <DButton
          class="btn-primary create"
          @action={{this.submit}}
          @label="chat.create_channel.create"
        />
      </:footer>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import { i18n } from "discourse-i18n";
import {
  CHAT_CHANNEL_LIST_ACTIVE_DAYS,
  CHAT_CHANNEL_LIST_FILTERS,
} from "discourse/plugins/chat/discourse/lib/chat-constants";

export default class ChatChannelListFilterMenu extends Component {
  @service chatChannelListPreferences;

  get section() {
    return this.args.section ?? "channels";
  }

  get currentFilter() {
    return this.chatChannelListPreferences.filterFor(this.section);
  }

  get isSaving() {
    return this.chatChannelListPreferences.isSavingFilterFor(this.section);
  }

  @action
  async selectFilter(filter) {
    const preferences = this.chatChannelListPreferences;
    const { closeParent, closeSubmenu } = this.args;
    const section = this.section;

    await closeSubmenu?.();
    await closeParent?.();
    await preferences.setFilter(section, filter);
  }

  <template>
    <DDropdownMenu
      aria-label={{i18n "chat.channel_list.filter.title"}}
      class="chat-channel-list-filter-menu"
      role="group"
      ...attributes
      as |dropdown|
    >
      <dropdown.subheader role="presentation">
        {{i18n "chat.channel_list.filter.title"}}
      </dropdown.subheader>

      <dropdown.item role="none">
        <DButton
          aria-checked={{if
            (eq this.currentFilter CHAT_CHANNEL_LIST_FILTERS.ALL)
            "true"
            "false"
          }}
          class="chat-channel-list-filter-menu__all"
          data-menu-option-id="all"
          role="menuitemradio"
          @action={{this.selectFilter}}
          @actionParam={{CHAT_CHANNEL_LIST_FILTERS.ALL}}
          @disabled={{this.isSaving}}
          @icon="check"
          @label="chat.channel_list.filter.all"
        />
      </dropdown.item>

      <dropdown.item role="none">
        <DButton
          aria-checked={{if
            (eq this.currentFilter CHAT_CHANNEL_LIST_FILTERS.ACTIVE)
            "true"
            "false"
          }}
          class="chat-channel-list-filter-menu__active --with-description"
          data-menu-option-id="active"
          role="menuitemradio"
          @action={{this.selectFilter}}
          @actionParam={{CHAT_CHANNEL_LIST_FILTERS.ACTIVE}}
          @disabled={{this.isSaving}}
          @icon="check"
        >
          <span class="chat-channel-list-filter-menu__label">
            <span class="chat-channel-list-filter-menu__label-title">
              {{i18n "chat.channel_list.filter.active"}}
            </span>
            <span class="chat-channel-list-filter-menu__label-description">
              {{i18n
                "chat.channel_list.filter.active_description"
                days=CHAT_CHANNEL_LIST_ACTIVE_DAYS
              }}
            </span>
          </span>
        </DButton>
      </dropdown.item>

      <dropdown.item role="none">
        <DButton
          aria-checked={{if
            (eq this.currentFilter CHAT_CHANNEL_LIST_FILTERS.UNREAD)
            "true"
            "false"
          }}
          class="chat-channel-list-filter-menu__unread"
          data-menu-option-id="unread"
          role="menuitemradio"
          @action={{this.selectFilter}}
          @actionParam={{CHAT_CHANNEL_LIST_FILTERS.UNREAD}}
          @disabled={{this.isSaving}}
          @icon="check"
          @label="chat.channel_list.filter.unread"
        />
      </dropdown.item>

      <dropdown.item role="none">
        <DButton
          aria-checked={{if
            (eq this.currentFilter CHAT_CHANNEL_LIST_FILTERS.MENTIONS)
            "true"
            "false"
          }}
          class="chat-channel-list-filter-menu__mentions"
          data-menu-option-id="mentions"
          role="menuitemradio"
          @action={{this.selectFilter}}
          @actionParam={{CHAT_CHANNEL_LIST_FILTERS.MENTIONS}}
          @disabled={{this.isSaving}}
          @icon="check"
          @label="chat.channel_list.filter.mentions"
        />
      </dropdown.item>
    </DDropdownMenu>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";
import { CHAT_CHANNEL_LIST_SORTS } from "discourse/plugins/chat/discourse/lib/chat-constants";

export const SORT_OPTIONS = [
  {
    value: CHAT_CHANNEL_LIST_SORTS.ALPHABETICAL,
    className: "chat-channel-list-sort-menu__alphabetical",
    dataOptionId: "alphabetical",
