  if (!message) {
    return;
  }

  if (message?.deletedAt && opts.autoExpand) {
    message.expanded = true;
  }

  if (opts.highlight) {
    message.highlight();
  }

  const scroll = () => {
    const element = list.querySelector(
      `.chat-message-container[data-id='${message.id}']`
