import Component from "@glimmer/component";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import getURL from "discourse/lib/get-url";
import { i18n } from "discourse-i18n";

export default class ChatRetentionReminderText extends Component {
  @service currentUser;
  @service siteSettings;

  get type() {
    return this.args.type ?? "long";
  }

  get #chatSettingsLink() {
    const label = i18n("chat.retention_reminders.chat_settings");
    if (this.currentUser?.admin) {
      const url = getURL("/admin/site_settings/category/chat");
      return `<a href="${url}">${label}</a>`;
    }
    return label;
  }

  get text() {
    const opts = { chatSettingsLink: this.#chatSettingsLink };
    const count = this.#countForChannelType;

    if (count > 0) {
      return trustHTML(
        i18n(`chat.retention_reminders.${this.type}`, { ...opts, count })
      );
    } else {
      return trustHTML(
        i18n(`chat.retention_reminders.indefinitely_${this.type}`, opts)
      );
    }
  }

  get #countForChannelType() {
    return this.args.channel.isDirectMessageChannel
      ? this.siteSettings.chat_dm_retention_days
      : this.siteSettings.chat_channel_retention_days;
  }

  <template>
    <span class="chat-retention-reminder-text">
      {{this.text}}
    </span>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import ChatRetentionReminderText from "discourse/plugins/chat/discourse/components/chat-retention-reminder-text";

export default class ChatRetentionReminder extends Component {
  @service currentUser;

  get show() {
    return (
      (this.args.channel?.isDirectMessageChannel &&
        this.currentUser?.get("needs_dm_retention_reminder")) ||
      (this.args.channel?.isCategoryChannel &&
        this.currentUser?.get("needs_channel_retention_reminder"))
    );
  }

  @action
  async dismiss() {
    try {
      await ajax("/chat/dismiss-retention-reminder", {
        method: "POST",
        data: { chatable_type: this.args.channel.chatableType },
      });
      const field = this.args.channel.isDirectMessageChannel
        ? "needs_dm_retention_reminder"
        : "needs_channel_retention_reminder";
      this.currentUser.set(field, false);
    } catch (e) {
      popupAjaxError(e);
    }
  }

  <template>
    {{#if this.show}}
      <div class="chat-retention-reminder">
        <ChatRetentionReminderText @channel={{@channel}} />
        <DButton
          class="no-text btn-icon btn-transparent dismiss-btn"
          @action={{this.dismiss}}
          @icon="xmark"
        />
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import ChatNotice from "./chat-notice.gjs";
import ChatRetentionReminder from "./chat-retention-reminder.gjs";

export default class ChatNotices extends Component {
  @service("chat-channel-notices-manager") noticesManager;

  get noticesForChannel() {
    return this.noticesManager.notices.filter(
      (notice) => notice.channelId === this.args.channel.id
    );
  }

  <template>
    <div class="chat-notices">
      <ChatRetentionReminder @channel={{@channel}} />

      {{#each this.noticesForChannel as |notice|}}
        <ChatNotice @channel={{@channel}} @notice={{notice}} />
      {{/each}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { trustHTML } from "@ember/template";

export default class ChatSkeleton extends Component {
  get placeholders() {
    return Array.from({ length: 15 }, () => {
      return {
        image: this.#randomIntFromInterval(1, 10) === 5,
        rows: Array.from({ length: this.#randomIntFromInterval(1, 5) }, () => {
          return trustHTML(`width: ${this.#randomIntFromInterval(20, 95)}%`);
        }),
        reactions: Array.from({ length: this.#randomIntFromInterval(0, 3) }),
      };
    });
  }

  #randomIntFromInterval(min, max) {
    return Math.floor(Math.random() * (max - min + 1) + min);
  }

  <template>
    <div class="chat-skeleton --animation">
      {{#each this.placeholders as |placeholder|}}
        <div class="chat-skeleton__body">
          <div class="chat-skeleton__message">
            <div class="chat-skeleton__message-avatar"></div>
            <div class="chat-skeleton__message-poster"></div>
            <div class="chat-skeleton__message-content">
              {{#if placeholder.image}}
                <div class="chat-skeleton__message-img"></div>
              {{/if}}

              <div class="chat-skeleton__message-text">
                {{#each placeholder.rows as |row|}}
                  <div class="chat-skeleton__message-msg" style={{row}}></div>
                {{/each}}
              </div>

              {{#if placeholder.reactions}}
                <div class="chat-skeleton__message-reactions">
                  {{#each placeholder.reactions}}
                    <div class="chat-skeleton__message-reaction"></div>
                  {{/each}}
                </div>
              {{/if}}
            </div>
          </div>
        </div>
      {{/each}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { i18n } from "discourse-i18n";
import ChatThread from "discourse/plugins/chat/discourse/models/chat-thread";

export default class ChatUploadDropZone extends Component {
