import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn, hash } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import didUpdate from "@ember/render-modifiers/modifiers/did-update";
import { service } from "@ember/service";
import { isBlank } from "@ember/utils";
import DMenu from "discourse/float-kit/components/d-menu";
import { ajax } from "discourse/lib/ajax";
import discourseDebounce from "discourse/lib/debounce";
import { bind } from "discourse/lib/decorators";
import { INPUT_DELAY } from "discourse/lib/environment";
import DiscourseURL from "discourse/lib/url";
import DButton from "discourse/ui-kit/d-button";
import DConditionalLoadingSpinner from "discourse/ui-kit/d-conditional-loading-spinner";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import DFilterInput from "discourse/ui-kit/d-filter-input";
import DLoadMore from "discourse/ui-kit/d-load-more";
import dAutoFocus from "discourse/ui-kit/modifiers/d-auto-focus";
import dTabToSibling from "discourse/ui-kit/modifiers/d-tab-to-sibling";
import { i18n } from "discourse-i18n";
import ChatChannelTitle from "discourse/plugins/chat/discourse/components/chat-channel-title";
import ChatMessageComponent from "discourse/plugins/chat/discourse/components/chat-message";
import ChatThreadHeading from "discourse/plugins/chat/discourse/components/chat-thread-heading";
import ChatChannel from "discourse/plugins/chat/discourse/models/chat-channel";
import ChatMessage from "discourse/plugins/chat/discourse/models/chat-message";

const LIMIT = 20;

export default class ChatSearch extends Component {
  @service chatSearchQuery;
  @service router;

  @tracked currentSort = "relevance";
  @tracked messages = [];
  @tracked isLoading = false;
  @tracked offset = 0;
  @tracked hasMoreResults = false;
  @tracked lastQuery = null;

  get enableQueryParams() {
    return this.args.enableQueryParams ?? true;
  }

  @bind
  async searchMessages(resetResults = true) {
    this.searchPromise?.abort();

    if (isBlank(this.args.query)) {
      this.messages = [];
      this.offset = 0;
      this.hasMoreResults = false;
      return;
    }

    this.isLoading = true;

    if (resetResults) {
      this.offset = 0;
      this.messages = [];
    }

    try {
      this.searchPromise = ajax("/chat/api/search", {
        data: {
          query: this.args.query,
          channel_id: this.args.scopedChannelId,
          sort: this.currentSort,
          offset: this.offset,
          limit: LIMIT,
        },
      });

      const response = await this.searchPromise;

      const newMessages = (response.messages || []).map((messageObject) => {
        return ChatMessage.create(
          ChatChannel.create(messageObject.channel),
          messageObject
        );
      });

      if (resetResults) {
        this.messages = newMessages;
      } else {
        this.messages = [...this.messages, ...newMessages];
      }

      this.offset += newMessages.length;
      this.hasMoreResults = response.meta?.has_more || false;

      return this.messages;
    } finally {
      this.isLoading = false;
    }
  }

  @action
  sortLabel(sort) {
    return i18n(`chat.search.sort.${sort}`);
  }

  @action
  setCurrentSorting(sort, closeMenu) {
    this.currentSort = sort;
    closeMenu();
    this.searchMessages(true);
  }

  @action
  onFilterChange(element) {
    const value = element.target.value;
    this.debouncedHandler = discourseDebounce(
      this.debounceFilterChange,
      value === "" ? null : value,
      INPUT_DELAY
    );
  }

  @action
  async loadMore() {
    if (!this.hasMoreResults || this.isLoading) {
      return;
    }

    await this.searchMessages(false);
  }

  @action
  debounceFilterChange(query) {
    this.chatSearchQuery.query = query;

    if (this.enableQueryParams) {
      this.router.replaceWith({ queryParams: { q: query } });
    }
  }

  @action
  checkQueryChange() {
    if (this.lastQuery !== this.args.query) {
      this.lastQuery = this.args.query;
      this.searchMessages(true);
    }
  }

  @action
  visitMessage(message) {
    DiscourseURL.routeTo(message.url);
  }

  @action
  handleKeypress(message, event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.visitMessage(message);
    }
  }

  accessibleMessageLabel(message) {
    const username = message.user?.username || i18n("chat.deleted_user");
    const messagePreview =
      message.excerpt ||
      (message.message ? message.message.substring(0, 100) + "..." : "");
    const threadInfo = message.threadTitle
      ? i18n("chat.search_view.in_thread", { title: message.threadTitle })
      : "";

    return i18n("chat.search_view.message_result_label", {
      username,
      preview: messagePreview,
      threadInfo,
    }).trim();
  }

  <template>
    <div
      class="c-search"
      {{didInsert this.checkQueryChange}}
      {{didUpdate this.checkQueryChange @query}}
    >
      <div class="chat-search__filters">
        <DFilterInput
          class="no-blur"
          placeholder={{i18n "chat.search_view.filter_placeholder"}}
          @filterAction={{this.onFilterChange}}
          @icons={{hash left="magnifying-glass"}}
          @onClearInput={{fn this.debounceFilterChange ""}}
          @value={{@query}}
          {{dAutoFocus}}
        />

        <DMenu
          @icon="sort"
          @identifier="search-sort-options"
          @label={{this.sortLabel this.currentSort}}
        >
          <:content as |menu|>
            <DDropdownMenu as |dropdown|>
              <dropdown.item>
                <DButton
                  class="btn-transparent"
                  @action={{fn this.setCurrentSorting "relevance" menu.close}}
                  @translatedLabel={{this.sortLabel "relevance"}}
                />
              </dropdown.item>
              <dropdown.item>
                <DButton
                  class="btn-transparent"
                  @action={{fn this.setCurrentSorting "latest" menu.close}}
                  @translatedLabel={{this.sortLabel "latest"}}
                />
              </dropdown.item>
            </DDropdownMenu>
          </:content>
        </DMenu>
      </div>

      {{#if @query.length}}
        {{#if this.messages.length}}
          <div class="sr-only" id="chat-search-instructions">
            {{i18n "chat.search_view.sr_instructions"}}
          </div>

          <ul
            aria-label={{i18n "chat.search_view.results_list_label"}}
            class="chat-message-search-entries"
            role="listbox"
          >
            {{#each this.messages key="id" as |message|}}
              <li
                aria-describedby="chat-search-instructions"
                aria-label={{this.accessibleMessageLabel message}}
                class="chat-message-search-entry"
                role="option"
                tabindex="0"
                {{on "click" (fn this.visitMessage message)}}
                {{on "keydown" (fn this.handleKeypress message)}}
                {{dTabToSibling}}
              >
                <div class="chat-message-search-entry__info">
                  {{#unless @scopedChannelId}}
                    <ChatChannelTitle @channel={{message.channel}} />
                  {{/unless}}

                  <ChatThreadHeading
                    @thread={{hash title=message.threadTitle}}
                  />
                </div>

                <ChatMessageComponent
                  @dateMode="long"
                  @disableMouseEvents={{true}}
                  @includeSeparator={{false}}
                  @interactive={{false}}
                  @message={{message}}
                />
              </li>
            {{/each}}
          </ul>

          <div class="chat-search-loading">
            <DConditionalLoadingSpinner @condition={{this.isLoading}} />
          </div>

          {{#if this.hasMoreResults}}
            <DLoadMore @action={{this.loadMore}} />
          {{/if}}

          <br />
        {{else if (not this.isLoading)}}
          <div class="alert alert-info">
            {{i18n "chat.search.no_results"}}
          </div>
        {{/if}}
      {{/if}}
    </div>
  </template>
}
const ChatSidePanelResizer = <template>
  <div class="chat-side-panel-resizer"></div>
</template>;

export default ChatSidePanelResizer;
import Component from "@glimmer/component";
import { hash } from "@ember/helper";
import { action } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import { service } from "@ember/service";
import KeyValueStore from "discourse/lib/key-value-store";
import resizableNode from "../modifiers/chat/resizable-node.js";
import ChatSidePanelResizer from "./chat-side-panel-resizer.gjs";

const MIN_PANEL_WIDTH = 250;
const STORE_NAMESPACE = "discourse_chat_side_panel_size_";

export default class ChatSidePanel extends Component {
  @service chatStateManager;
  @service site;

  store = new KeyValueStore(STORE_NAMESPACE);

  get mainContainerWidth() {
    return document.getElementById("main-chat-outlet").clientWidth;
  }

  @action
  setupSize(element) {
    if (this.site.mobileView) {
      return;
    }

    if (!this.chatStateManager.isFullPageActive) {
      return;
    }

    const validWidth = Math.min(
      this.store.getObject("width") ?? MIN_PANEL_WIDTH,
      this.mainContainerWidth - MIN_PANEL_WIDTH
    );

    element.animate(
      [{ width: element.style.width }, { width: validWidth + "px" }],
      { duration: 0, fill: "forwards" }
    );
    this.storeWidth(validWidth);
  }

  @action
  didResize(element, size) {
    const mainPanelWidth = this.mainContainerWidth - size.width;

    if (size.width >= MIN_PANEL_WIDTH && mainPanelWidth >= MIN_PANEL_WIDTH) {
      element.animate(
        [{ width: element.style.width }, { width: size.width + "px" }],
        { duration: 0, fill: "forwards" }
      );
      this.storeWidth(size.width);
    }
  }

  storeWidth(width) {
    this.store.setObject({
      key: "width",
      value: width,
    });
  }

  <template>
    {{#if this.chatStateManager.isSidePanelExpanded}}
      <div
        class="chat-side-panel"
        {{didInsert this.setupSize}}
        {{resizableNode
          ".chat-side-panel-resizer"
          this.didResize
          (hash
            position=false vertical=false mutate=false resetOnWindowResize=true
          )
        }}
      >
        {{yield}}

        {{#if this.site.desktopView}}
          <ChatSidePanelResizer />
        {{/if}}
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import DUserStatusMessage from "discourse/ui-kit/d-user-status-message";
import dIcon from "discourse/ui-kit/helpers/d-icon";

/**
 * Displays unread indicators and user status for chat channels in the sidebar.
 *
 * @component ChatSidebarIndicators
 * @param {Object} @suffixArgs - Arguments object when used as @suffixComponent
 * @param {number} @suffixArgs.unreadCount - Number of unread messages
 * @param {number} @suffixArgs.unreadThreadsCount - Number of unread threads
 * @param {number} @suffixArgs.mentionCount - Number of unread mentions
 * @param {number} @suffixArgs.watchedThreadsUnreadCount - Number of unread watched threads
 * @param {boolean} @suffixArgs.isDirectMessageChannel - Whether this is a DM channel
 * @param {Object} @suffixArgs.userStatus - User status object for DM channels
 */
export default class ChatSidebarIndicators extends Component {
  /**
   * Determines if the channel has any unread content (messages, threads, mentions, or watched threads).
   *
   * @returns {boolean} True if there are any unreads that should show an indicator
   */
  get hasUnread() {
    return (
      this.args.suffixArgs?.unreadCount > 0 ||
      this.args.suffixArgs?.unreadThreadsCount > 0 ||
      this.args.suffixArgs?.mentionCount > 0 ||
      this.args.suffixArgs?.watchedThreadsUnreadCount > 0
    );
  }

  /**
   * Determines the urgency class for the unread indicator.
   * Returns "urgent" for mentions, watched threads, or any DM unreads.
   * Returns "unread" for regular unread messages.
   *
   * @returns {string} CSS class name - either "urgent" or "unread"
   */
  get urgencyClass() {
    const hasUrgent =
      this.args.suffixArgs?.mentionCount > 0 ||
      this.args.suffixArgs?.watchedThreadsUnreadCount > 0;

    // For DMs, treat all unreads as urgent
    const hasUnreadDM =
      this.args.suffixArgs?.isDirectMessageChannel &&
      this.args.suffixArgs?.unreadCount > 0;

    if (hasUrgent || hasUnreadDM) {
      return "urgent";
    }
    return "unread";
  }

  <template>
    {{#if @suffixArgs.userStatus}}
      <DUserStatusMessage @status={{@suffixArgs.userStatus}} />
    {{/if}}
    {{#if this.hasUnread}}
      <span
        class="sidebar-section-link-content-badge icon {{this.urgencyClass}}"
      >{{dIcon "circle"}}</span>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";

const MAX_UNREAD_COUNT = 99;

export default class ChatThreadUnreadIndicator extends Component {
  get unreadCount() {
    return this.args.thread.tracking.unreadCount;
  }

  get urgentCount() {
    return (
      this.args.thread.tracking.mentionCount +
      this.args.thread.tracking.watchedThreadsUnreadCount
    );
  }

  get showUnreadIndicator() {
    return this.unreadCount > 0 || this.urgentCount > 0;
  }

  get unreadCountLabel() {
    const count = this.urgentCount > 0 ? this.urgentCount : this.unreadCount;
    return count > MAX_UNREAD_COUNT ? `${MAX_UNREAD_COUNT}+` : count;
  }

  get isUrgent() {
    return this.urgentCount > 0 ? "-urgent" : "";
  }

  <template>
    {{#if this.showUnreadIndicator}}
      <span
        class="c-unread-indicator chat-thread-list-item-unread-indicator
          {{this.isUrgent}}"
      >
        <span
          class="c-unread-indicator__number chat-thread-list-item-unread-indicator__number"
        >
          {{this.unreadCountLabel}}
        </span>
      </span>
    {{/if}}
  </template>
}
