            {{on "click" this.toggleDisabled}}
          />
        </Row>
        <Row @name="Sending">
          <DToggleSwitch
            @state={{this.chatChannelPane.sending}}
            {{on "click" this.toggleSending}}
          />
        </Row>
      </Controls>
    </StyleguideExample>
  </template>
