    suffixType = "icon";
    hoverType = "icon";

    constructor({
      channel,
      chatService,
      currentUser,
      siteSettings,
      chatStateManager,
    }) {
      super(...arguments);
      this.channel = channel;
      this.chatService = chatService;
      this.siteSettings = siteSettings;
      this.currentUser = currentUser;
      this.chatStateManager = chatStateManager;

      if (this.isOneOnOneDM) {
        const user = this.channel.chatable.users?.[0];
        if (user?.username !== i18n("chat.deleted_chat_username")) {
          user.statusManager.trackStatus();
        }
      }
    }

    @bind
    willDestroy() {
      if (this.isOneOnOneDM) {
        this.channel.chatable.users?.[0]?.statusManager?.stopTrackingStatus();
      }
    }

    get isDM() {
      return this.channel.isDirectMessageChannel;
    }

    get isOneOnOneDM() {
      return this.isDM && this.channel.chatable.users.length === 1;
    }

    get name() {
      return this.isDM
        ? this.channel.slugifiedTitle
        : dasherize(this.channel.slugifiedTitle);
    }

    get classNames() {
      const classes = [];

      if (this.channel.currentUserMembership?.muted) {
        classes.push("sidebar-section-link--muted");
      }

      if (
        this.channel.id === this.chatService.activeChannel?.id &&
        (this.chatStateManager.isDrawerExpanded ||
          this.chatStateManager.isFullPageActive)
      ) {
        classes.push("sidebar-section-link--active");
      }

      classes.push(`channel-${this.channel.id}`);

      return classes.join(" ");
    }

    get models() {
      return this.channel.routeModels;
    }

    get text() {
      if (this.isDM) {
        if (this.channel.chatable.group) {
          return this.channel.displayTitle;
        } else {
          const username = this.channel.escapedTitle.replaceAll("@", "");
          return trustHTML(
            `${escapeExpression(username)}${decorateUsername(
              escapeExpression(username)
            )}`
          );
        }
      } else {
        return trustHTML(emojiUnescape(this.channel.escapedTitle));
      }
    }

    get title() {
      if (this.isDM) {
        if (this.channel.chatable.group) {
          return i18n("chat.placeholder_channel", {
            channelName: this.channel.escapedTitle,
          });
        } else {
          return i18n("chat.placeholder_users", {
            commaSeparatedNames: this.channel.escapedTitle,
          });
        }
      } else {
        return this.channel.escapedDescription
          ? trustHTML(this.channel.escapedDescription)
          : `${this.channel.escapedTitle} ${i18n("chat.title")}`;
      }
    }

    get prefixType() {
      if (this.isDM) {
        if (displayedEmoji(this.channel)) {
          return "emoji";
        } else if (this.channel.chatable.group) {
          if (this.channel.chatable.users.length === 1) {
            return "image";
          } else {
            return "text";
          }
        } else {
          return "image";
        }
      } else {
        return displayedEmoji(this.channel) ? "emoji" : "icon";
      }
    }

    get prefixValue() {
      if (this.isDM) {
        if (displayedEmoji(this.channel)) {
          return displayedEmoji(this.channel);
        } else if (this.channel.chatable.group) {
          if (this.channel.chatable.users.length === 1) {
            return avatarUrl(
              this.channel.chatable.users[0].avatar_template,
              "tiny"
            );
          } else {
            return this.channel.membershipsCount;
          }
        } else {
          return avatarUrl(
            this.channel.chatable.users[0].avatar_template,
            "tiny"
          );
        }
      } else {
        return displayedEmoji(this.channel) ?? "d-chat";
      }
    }

    get prefixColor() {
      return this.isDM ? null : this.channel.chatable.color;
    }

    get prefixBadge() {
      return !this.isDM && this.channel.chatable.read_restricted ? "lock" : "";
    }

    get prefixCSSClass() {
      if (this.isDM) {
        const activeUsers = this.chatService.presenceChannel.users;
        const user = this.channel.chatable.users[0];

        if (
          !!activeUsers?.find((item) => get(item, "id") === user?.id) ||
          !!activeUsers?.find(
            (item) => get(item, "username") === user?.username
          )
        ) {
          return "active";
        }
      }
      return "";
    }

    get suffixComponent() {
      return ChatSidebarIndicators;
    }

    get suffixArgs() {
      if (this.isDM) {
        return {
          userStatus: this.isOneOnOneDM
            ? this.channel.chatable.users[0].get("status")
            : null,
          unreadCount: this.channel.tracking.unreadCount,
          unreadThreadsCount: this.channel.unreadThreadsCountSinceLastViewed,
          mentionCount: this.channel.tracking.mentionCount,
          watchedThreadsUnreadCount:
            this.channel.tracking.watchedThreadsUnreadCount,
          isDirectMessageChannel: true,
        };
      } else {
        return {
          unreadCount: this.channel.tracking.unreadCount,
          unreadThreadsCount:
            this.chatService.activeChannel?.id !== this.channel.id
              ? this.channel.unreadThreadsCountSinceLastViewed
              : 0,
          mentionCount: this.channel.tracking.mentionCount,
          watchedThreadsUnreadCount:
            this.channel.tracking.watchedThreadsUnreadCount,
          isDirectMessageChannel: false,
        };
      }
    }

    get suffixValue() {
      return showSuffix ? "" : "";
    }

    get suffixCSSClass() {
      return showSuffix ? "" : "";
    }
  };
}

function channelListActions(section, menuService, preferences, links) {
  const actions = [];
  const bypassed = preferences.isFilterBypassedFor(section);
  if (bypassed || (!preferences.isDefaultFilterFor(section) && !links.length)) {
    actions.push({
      id: "toggleChannelFilter",
      icon: bypassed ? "filter" : "filter-circle-xmark",
      title: i18n(
        bypassed
          ? "chat.channel_list.apply_filters"
          : "chat.channel_list.empty.show_all"
      ),
      disabled: preferences.isSavingFilterFor(section),
      action: () => preferences.toggleFilter(section),
    });
  }
  actions.push(channelListOptionsAction(section, menuService));
  return actions;
}

function channelListOptionsAction(section, menuService) {
  return {
    id: "channelListOptions",
    title: i18n("chat.channel_list.options.title"),
    action: (event) => {
      menuService.show(event.currentTarget, {
        component: ChatChannelListSidebarMenu,
        contentRole: "menu",
        identifier: "chat-channel-list-options-menu",
        modalForMobile: true,
        placement: "right-start",
        data: { section, ...CHANNEL_LIST_SECTION_OPTIONS[section] },
      });
    },
  };
}

// Emoji are skipped while disabled so the prefix falls back to the channel's
// icon, avatar, or member count instead of rendering the raw `:code:`.
function displayedEmoji(channel) {
  return helperContext().siteSettings.enable_emoji ? channel.emoji : null;
}

