      this,
      this.callback,
      event,
      this.options.delay ?? 100,
      this.options.immediate ?? false
    );
  }

  cleanup() {
    cancel(this.throttledHandler);
    this.element.removeEventListener("scroll", this.throttledCallback);
  }
}
